 "content": "from collections import deque


def _normalize(cells):
    min_r = min(r for r, c in cells)
    min_c = min(c for r, c in cells)
    return {(r - min_r, c - min_c) for r, c in cells}


def _components(grid, color, min_col):
    h, w = len(grid), len(grid[0])
    seen = set()
    result = []
    for r in range(h):
        for c in range(min_col, w):
            if grid[r][c] != color or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = set()
            while stack:
                y, x = stack.pop()
                cells.add((y, x))
                for ny, nx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0 <= ny < h and min_col <= nx < w and (ny,nx) not in seen and grid[ny][nx] == color:
                        seen.add((ny,nx))
                        stack.append((ny,nx))
            result.append(cells)
    return result


def transform(grid):
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    frame = next((g[0][c] for c in range(1, w) if all(row[c] == g[0][c] for row in g)), None)
    if frame is None:
        return g
    left_edge = max(c for c in range(1, w) if all(row[c] == frame for row in g))
    separators = [r for r in range(h) if all(g[r][c] == frame for c in range(left_edge + 1))]
    bands = []
    for a, b in zip(separators, separators[1:]):
        cells = {(r, c) for r in range(a + 1, b) for c in range(1, left_edge) if g[r][c] != frame}
        if cells:
            bands.append((cells, _normalize(cells)))
    objects = []
    colors = sorted({g[r][c] for r in range(h) for c in range(left_edge + 1, w) if g[r][c] not in (0, frame)})
    for color in colors:
        objects.extend((color, cells, _normalize(cells)) for cells in _components(g, color, left_edge + 1))
    for band_cells, shape in bands:
        matches = [(color, obj) for color, obj, obj_shape in objects if obj_shape == shape]
        if matches:
            color = matches[0][0]
            for r, c in band_cells:
                g[r][c] = color
    return g
